allow:
Bash(powershell -Command "
$content = Get-Content ChatMessages.tsx -Raw

# Add new imports
$oldImports = ""import type { Message } from ''./index'';
import { AgentProgressIndicator } from ''./AgentProgressIndicator'';""

$newImports = ""import { useQuery } from ''@tanstack/react-query'';
import type { Message } from ''./index'';
import { AgentProgressIndicator } from ''./AgentProgressIndicator'';
import { InlineActionCard, type PendingActionData } from ''./InlineActionCard'';
import { multiAgentApi } from ''@/lib/api/ai'';""

$content = $content -replace [regex]::Escape\($oldImports\), $newImports

# Add hook and component after interface
$oldInterface = ''interface ChatMessagesProps {
  messages: Message[];
  sending: boolean;
}

// Markdown''

$newInterface = ''interface ChatMessagesProps {
  messages: Message[];
  sending: boolean;
}

// Hook to fetch pending actions for a message
function usePendingActionsForMessage\(actionIds: string[] | undefined\) {
  return useQuery\({
    queryKey: [""ai"", ""pendingActions"", ""inline"", actionIds?.join\("",""\) || """"],
    queryFn: async \(\) => {
      if \(!actionIds || actionIds.length === 0\) return [];
      const response = await multiAgentApi.getPendingActions\({ limit: 50 }\);
      const allActions = response.data?.actions || [];
      return allActions.filter\(\(a: PendingActionData\) => actionIds.includes\(a.id\)\);
    },
    enabled: !!actionIds && actionIds.length > 0,
    staleTime: 10 * 1000,
    refetchInterval: 5 * 1000,
  }\);
}

// Component to render inline actions for a message
function MessageInlineActions\({ actionIds }: { actionIds: string[] }\) {
  const { data: actions = [] } = usePendingActionsForMessage\(actionIds\);
  if \(!actions.length\) return null;
  return \(
    <Box sx={{ mt: 1 }}>
      {actions.map\(\(action: PendingActionData\) => \(
        <InlineActionCard key={action.id} action={action} />
      \)\)}
    </Box>
  \);
}

// Markdown''

$content = $content -replace [regex]::Escape\($oldInterface\), $newInterface

# Add inline action card rendering after Paper component
$oldPaper = ''</Paper>

            {/\\* Metadata \\*/}''

$newPaper = ''</Paper>

            {/\\* Inline Action Cards - Show below assistant messages with pending actions \\*/}
            {message.role === ""assistant"" && message.pendingActionIds && message.pendingActionIds.length > 0 && \(
              <MessageInlineActions actionIds={message.pendingActionIds} />
            \)}

            {/\\* Metadata \\*/}''

$content = $content -replace [regex]::Escape\($oldPaper\), $newPaper

Set-Content -Path ChatMessages.tsx -Value $content -NoNewline
Write-Host ''File updated successfully''
")
